      SUBROUTINE RDTYPE(KWORD,LWORD)C---- READ AN IDENTIFIER OR KEYWORD OF UP TO 15 CHARACTERSC-------------------------------------------------------------------      CHARACTER*15    KWORDC-------------------------------------------------------------------      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCHAR.CIN'C-------------------------------------------------------------------C      KWORD = '        '      LWORD = 0      IF (INDEX(ALFNUM,ITEM) .NE. 0) THEN   10   CONTINUE          IF (LWORD .LT. 15) THEN            LWORD = LWORD + 1            KWORD(LWORD:LWORD) = ITEM          ENDIF          CALL RDFWRD        IF (INDEX(ALFNUM,ITEM) .NE. 0) GO TO 10        CALL RDBACK      ENDIF      RETURN      END